/// <summary>/// Collection will display as a ComboBox in PropertyGrid on the fly./// <code>/// @example/// [CategoryAttribute("KOMPONENTY"),/// DisplayName("Vrstva"),/// DescriptionAttribute("Upravit vrstvu"),/// TypeConverter(typeof(ListObjectConverter))/// ]/// ListObject SelectedComponent { get; set; }/// /// new public enum ImageLayerType {///  Pozadí,///  Obarvení/// }/// public static List&lt;string&gt; SelectedComponentList =&gt; new ImageLayerType().ToNamesList();/// public ListObject layerComponent = new ListObject(0, "Pozadí");/// public ListObject LayerComponent {/// get => layerComponent;/// set {///   layerComponent = value;///   SelectedComponent = (ImageLayerType)Enum.Parse(typeof(ImageLayerType), value);///  }/// }/// </code>/// </summary>public class ListObjectConverter:StringConverter {	/// <summary> The names will be picked from Sprite.property which name is ending with "List" </summary>	private List<ListObject> Names;	public ListObjectConverter() => Names = new List<ListObject>();	public override bool GetStandardValuesSupported(ITypeDescriptorContext context) {		//true means show a combobox		return true;	}	public override bool GetStandardValuesExclusive(ITypeDescriptorContext context) {		//true will limit to list. false will show the list, 		//but allow free-form entry		return true;	}	public override bool CanConvertFrom(ITypeDescriptorContext context, Type sourceType) {		if (sourceType == typeof(string)) {			return true;		}		return base.CanConvertFrom(context, sourceType);	}	public override object ConvertFrom(ITypeDescriptorContext context, CultureInfo culture, object value) {		if (value is string s) {			// conversion logic goes here			var selectedItem = Names.FirstOrDefault(cel=> cel.Name == s);			return selectedItem ?? new ListObject(0, "empty");		}		return base.ConvertFrom(context, culture, value);	}	public override TypeConverter.StandardValuesCollection GetStandardValues(ITypeDescriptorContext context) {		//Console.WriteLine("ListObjectsConverter > GetStandardValues > Dict:\n\t{0}", Names.ListToString("\n\t"));		return new StandardValuesCollection(Names);	}	public override object ConvertTo(ITypeDescriptorContext context, CultureInfo culture, object value, Type destinationType) {		if (context != null && Names.Count == 0) {			// Get names from static property (like: "SelectedComponentList")			var sprite = context.Instance;			// SelectedComponent + "List" will get static property with names (Naming rules is important!)			var propName = context.PropertyDescriptor.Name + "List";			var propertyInfo = sprite.GetType().GetProperty(propName, BindingFlags.Public | BindingFlags.Static);			if (propertyInfo != null) {				IList list = propertyInfo.GetValue(sprite, null) as IList;				Names = list.Cast<string>().Select((v, i)=> new ListObject(i, v)).ToList();				//Console.WriteLine("ListObjectsConverter > ConvertTo >  propName:{0} Names:{1}", propName, Names);			}			//Console.WriteLine("ListObjectsConverter > ConvertTo >  Picked propName:{0} Names:{1}", propName, Names.First());			// show first selected name in list			return Names.First().Name;		}		if (value is ListObject c) {			//Console.WriteLine("ListObjectsConverter > ConvertTo >  ListObject:{0}", c);			// show first selected name in list			return c.Name;		} 		if (value is string s) {			//Console.WriteLine("ListObjectsConverter > ConvertTo >  String:{0}", s);			// show names in list			return s;		}		//Console.WriteLine("ListObjectsConverter > ConvertTo > other value:{0}", value);		return base.ConvertTo(context, culture, value, destinationType);	}}